		public static bool CheckTargetPokeID(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            uint targetCount = (uint)args.pEventSystem.EVENTVAR_GetValue(EventVar.Label.TARGET_POKECNT);
            for (uint i=0; i<targetCount; i++)
            {
                if (getTaragetPokeID(args.pEventSystem, (byte)i) == pokeID)
                    return true;
            }
            return false;
        }
		public static byte getTaragetPokeID(global::Dpr.Battle.Logic.EventSystem eventSystem, byte index) {
            if (index < (uint)eventSystem.EVENTVAR_GetValue(EventVar.Label.TARGET_POKECNT))
                return (byte)eventSystem.EVENTVAR_GetValue((EventVar.Label)((int)EventVar.Label.POKEID_TARGET1 + index));

            return PokeID.INVALID;
        }
		public static bool CheckTargetSide(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, global::Dpr.Battle.Logic.BtlSide side) {
            uint targetCount = (uint)args.pEventSystem.EVENTVAR_GetValue(EventVar.Label.TARGET_POKECNT);
            for (uint i=0; i<targetCount; i++)
            {
                byte targetPokeID = getTaragetPokeID(args.pEventSystem, (byte)i);
                if (args.pMainModule.PokeIDtoSide(targetPokeID) == side)
                    return true;
            }
            return false;
        }
		public static bool CheckPokeOrderLast(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            int actionCount = 0;
            int doneCount = 0;
            for (int i=0; i<args.pPokeActionContainer.GetCount(); i++)
            {
                PokeAction action = args.pPokeActionContainer.Get((byte)i);
                if (action.bpp != null && action.bpp.GetID() != pokeID)
                {
                    actionCount++;
                    if (action.fDone)
                        doneCount++;
                }
            }
            return actionCount == doneCount;
        }
		public static bool CheckActionDoneOnce(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            return args.pBattleEnv.GetPokeCon().GetPokeParamConst(pokeID).CONTFLAG_Get(ContFlag.CONTFLG_ACTION_DONE);
        }
		public static bool CheckUnbreakablePokeItem(ushort monsno, ushort itemID) {
            if (itemID == 0)
                return false;

            switch (monsno)
            {
                case (ushort)MonsNo.KAIOOGA:
                    return itemID == (ushort)ItemNo.AIIRONOTAMA;
                case (ushort)MonsNo.GURAADON:
                    return itemID == (ushort)ItemNo.BENIIRONOTAMA;
                case (ushort)MonsNo.ARUSEUSU:
                    return tables.IsMatchAruseusPlate(itemID);
                case (ushort)MonsNo.GIRATHINA:
                    return itemID == (ushort)ItemNo.HAKKINDAMA;
                default:
                    return Pml.Item.ItemData.IsPiece(itemID);
            }
        }
		public static bool CheckCantChangeItemPoke(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            BTL_POKEPARAM bpp = args.pBattleEnv.GetPokeCon().GetPokeParamConst(pokeID);
            return CheckUnbreakablePokeItem(bpp.GetMonsNo(), bpp.GetItem());
        }
		public static bool CheckCantStealWildPoke(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte attackPokeID) {
            if (GetRule(args) == BtlRule.BTL_RULE_RAID || GetCompetitor(args) != BtlCompetitor.BTL_COMPETITOR_WILD)
                return false;

            byte clientID = MainModule.PokeIDtoClientID(attackPokeID);
            return clientID == (byte)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1 || clientID == (byte)BTL_CLIENT_ID.BTL_CLIENT_ENEMY2;
        }
		public static bool CheckCantStealPoke(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte attackPokeID, byte targetPokeID) {
            if (CheckCantStealWildPoke(args, attackPokeID))
                return true;

            if (CheckCantChangeItemPoke(args, targetPokeID))
                return true;

            BTL_POKEPARAM attacker = args.pBattleEnv.GetPokeCon().GetPokeParamConst(attackPokeID);
            BTL_POKEPARAM target = args.pBattleEnv.GetPokeCon().GetPokeParamConst(targetPokeID);
            return CheckUnbreakablePokeItem(attacker.GetMonsNo(), target.GetItem());
        }
		public static bool CheckTameHidePoke(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            return args.pBattleEnv.GetPokeCon().GetPokeParamConst(pokeID).IsWazaHide();
        }
		public static void MagicCoat_CheckSideEffWaza(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (CheckTameHidePoke(args, pokeID))
                return;

            byte attackPokeID = (byte)GetEventVar(args, EventVar.Label.POKEID);
            if (args.pMainModule.IsFriendPokeID(attackPokeID, pokeID))
                return;

            WazaNo waza = (WazaNo)GetEventVar(args, EventVar.Label.WAZAID);
            if (WAZADATA.GetCategory(waza) != WazaCategory.SIDE_EFFECT || !WAZADATA.GetFlag(waza, WazaFlag.MAGIC_COAT))
                return;

            if (RewriteEventVar_FAIL_CAUSE(args, WazaFailCause.NO_REACTION))
                AddMagicCoatAction(args, pokeID, attackPokeID);
        }
		public static void MagicCoat_Wait(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (GetEventVar(args, EventVar.Label.MAGICCOAT_FLAG) != 0)
                return;

            if (GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
                return;

            if (GetPokeParam(args, pokeID).IsWazaHide())
                return;

            if (!WAZADATA.GetFlag((WazaNo)GetEventVar(args, EventVar.Label.WAZAID), WazaFlag.MAGIC_COAT))
                return;

            if (!RewriteEventVar(args, EventVar.Label.NOEFFECT_FLAG, 1))
                return;

            byte attackPokeID = (byte)GetEventVar(args, EventVar.Label.POKEID_ATK);
            BtlPokePos targetPos = args.pBattleEnv.GetPosPoke().GetPokeExistPos(attackPokeID);
            args.pSectionSharedData.GetActionSharedDataStack().GetCurrentData().magicCoatParam.Add(pokeID, attackPokeID, targetPos);
            args.pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.GEN_FLAG, 1);
        }
		public static void MagicCoat_Reaction(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            int eventPokeID = GetEventVar(args, EventVar.Label.POKEID);
            if (eventPokeID != pokeID)
                return;

            if (GetPokeParam(args, pokeID).IsWazaHide())
                return;

            Section_FromEvent_Message.Description desc = new Section_FromEvent_Message.Description();
            desc.pokeID = pokeID;
            desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.MagicCoatExe);
            desc.message.AddArg(eventPokeID);
            desc.message.AddArg(GetEventVar(args, EventVar.Label.WAZAID));
            Message(args, desc);
        }
