		public static uint GetKillCount(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (args.pEventSystem.EVENTVAR_GetValue(EventVar.Label.POKEID_ATK) != pokeID)
                return 0;

            uint killCount = 0;
            uint targetCount = (uint)args.pEventSystem.EVENTVAR_GetValue(EventVar.Label.TARGET_POKECNT);
            for (uint i=0; i<targetCount; i++)
            {
                byte targetPokeID = getTaragetPokeID(args.pEventSystem, (byte)i);
                if (targetPokeID != PokeID.INVALID && args.pBattleEnv.GetPokeCon().GetPokeParamConst(targetPokeID).IsDead())
                    killCount++;
            }
            return killCount;
        }
