		public static void SortTargetsByAgility(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte[] targetPokeIDAry, uint targetCount, byte myPokeID, bool bDownFriendPriority) {
            if (targetCount >= SortTargetsByAgility_rank.Length)
                return;

            for (int i=0; i<targetCount; i++)
            {
                Section_FromEvent_CalcAgilityOrder.Description desc = new Section_FromEvent_CalcAgilityOrder.Description();
                desc.target = args.pBattleEnv.GetPokeCon().GetPokeParamConst(targetPokeIDAry[i]);
                desc.isTrickRoomApply = true;
                SortTargetsByAgility_rank[i] = CalcAgilityOrder(args, desc);

                if (bDownFriendPriority && args.pMainModule.IsFriendPokeID(myPokeID, targetPokeIDAry[i]))
                    SortTargetsByAgility_rank[i] += 5;
            }

            for (int i=0; i<targetCount; i++)
            {
                for (int j=i+1; j<targetCount; j++)
                {
                    if (SortTargetsByAgility_rank[j] < SortTargetsByAgility_rank[i])
                    {
                        ushort tmpRank = SortTargetsByAgility_rank[i];
                        SortTargetsByAgility_rank[i] = SortTargetsByAgility_rank[j];
                        SortTargetsByAgility_rank[j] = tmpRank;

                        byte tmpPokeID = targetPokeIDAry[i];
                        targetPokeIDAry[i] = targetPokeIDAry[j];
                        targetPokeIDAry[j] = tmpPokeID;
                    }
                }
            }
        }
		public static global::Pml.PokePara.Sick CheckPokeSick(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            BTL_POKEPARAM bpp = args.pBattleEnv.GetPokeCon().GetPokeParamConst(pokeID);
            if (bpp != null)
                return bpp.GetPokeSick();

            return Sick.NONE;
        }
		public static bool CheckSimpleEffectOnlyAdvantage(global::Pml.WazaNo waza) {
            if (WAZADATA.GetCategory(waza) != WazaCategory.SIMPLE_EFFECT)
                return false;

            byte effectCount = WAZADATA.GetRankEffectCount(waza);
            if (effectCount == 0)
                return false;

            for (uint i=0; i<effectCount; i++)
            {
                WAZADATA.GetRankEffect(waza, i, out int volume);
                if (volume < 0)
                    return false;
            }
            return true;
        }
		public static void KonoyubiTomare_TemptTarget(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte konoyubiPokeID, global::Dpr.Battle.Logic.TemptTargetPriority temptPriority, global::Dpr.Battle.Logic.TemptTargetCause temptCause) {
            if (args.pMainModule.GetRule() == BtlRule.BTL_RULE_SINGLE)
                return;

            if (args.pMainModule.IsFriendPokeID(konoyubiPokeID, (byte)args.pEventSystem.EVENTVAR_GetValue(EventVar.Label.POKEID_ATK)))
                return;

            if (args.pEventSystem.EVENTVAR_GetValue(EventVar.Label.WAZAID) == (int)WazaNo.HURIIFOORU)
                return;

            if (args.pBattleEnv.GetPokeCon().GetPokeParamConst(konoyubiPokeID).CheckSick(WazaSick.WAZASICK_FREEFALL))
                return;

            if (CheckMemberOutInterruptActionProceeding(args))
                return;

            HandCommon_TemptTarget(args, konoyubiPokeID, temptPriority, temptCause);
        }
		public static void HandCommon_TemptTarget(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte temptPokeID, global::Dpr.Battle.Logic.TemptTargetPriority temptPriority, global::Dpr.Battle.Logic.TemptTargetCause temptCause) {
            if ((byte)args.pEventSystem.EVENTVAR_GetValue(EventVar.Label.TEMPT_TARGET_PRIORITY) < (byte)temptPriority)
            {
                args.pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.POKEID_DEF, temptPokeID);
                args.pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.TEMPT_TARGET_PRIORITY, (int)temptPriority);
                args.pEventSystem.EVENTVAR_RewriteValue(EventVar.Label.TEMPT_TARGET_CAUSE, (int)temptCause);
            }
        }
