		public static byte GetAllOpponentFrontPokeID(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte basePokeID, byte[] dst) {
            FrontPokeAccessor accessor = new FrontPokeAccessor(args.pMainModule, args.pBattleEnv);
            byte count = 0;
            while (accessor.GetNext(out BTL_POKEPARAM bpp))
            {
                if (args.pMainModule.IsFriendPokeID(basePokeID, bpp.GetID()))
                    continue;

                dst[count++] = bpp.GetID();
            }
            return count;
        }
